     1→//! Provides the `ObservedBlockProducers` struct which allows for rejecting gossip blocks from
     2→//! validators that have already produced a block.
     3→
     4→use std::collections::hash_map::Entry;
     5→use std::collections::{HashMap, HashSet};
     6→use std::marker::PhantomData;
     7→use types::{BeaconBlockRef, Epoch, EthSpec, Hash256, Slot, Unsigned};
     8→
     9→#[derive(Debug, PartialEq)]
    10→pub enum Error {
    11→    /// The slot of the provided block is prior to finalization and should not have been provided
    12→    /// to this function. This is an internal error.
    13→    FinalizedBlock { slot: Slot, finalized_slot: Slot },
    14→    /// The function to obtain a set index failed, this is an internal error.
    15→    ValidatorIndexTooHigh(u64),
    16→}
    17→
    18→#[derive(Eq, Hash, PartialEq, Debug, Default)]
    19→pub struct ProposalKey {
    20→    pub slot: Slot,
    21→    pub proposer: u64,
    22→}
    23→
    24→impl ProposalKey {
    25→    pub fn new(proposer: u64, slot: Slot) -> Self {
    26→        Self { slot, proposer }
    27→    }
    28→}
    29→
    30→/// Maintains a cache of observed `(block.slot, block.proposer)`.
    31→///
    32→/// The cache supports pruning based upon the finalized epoch. It does not automatically prune, you
    33→/// must call `Self::prune` manually.
    34→///
    35→/// The maximum size of the cache is determined by `slots_since_finality *
    36→/// VALIDATOR_REGISTRY_LIMIT`. This is quite a large size, so it's important that upstream
    37→/// functions only use this cache for blocks with a valid signature. Only allowing valid signed
    38→/// blocks reduces the theoretical maximum size of this cache to `slots_since_finality *
    39→/// active_validator_count`, however in reality that is more like `slots_since_finality *
    40→/// known_distinct_shufflings` which is much smaller.
    41→pub struct ObservedBlockProducers<E: EthSpec> {
    42→    finalized_slot: Slot,
    43→    items: HashMap<ProposalKey, HashSet<Hash256>>,
    44→    _phantom: PhantomData<E>,
    45→}
    46→
    47→impl<E: EthSpec> Default for ObservedBlockProducers<E> {
    48→    /// Instantiates `Self` with `finalized_slot == 0`.
    49→    fn default() -> Self {
    50→        Self {
    51→            finalized_slot: Slot::new(0),
    52→            items: HashMap::new(),
    53→            _phantom: PhantomData,
    54→        }
    55→    }
    56→}
    57→
    58→pub enum SeenBlock {
    59→    Duplicate,
    60→    Slashable,
    61→    UniqueNonSlashable,
    62→}
    63→
    64→impl SeenBlock {
    65→    pub fn proposer_previously_observed(self) -> bool {
    66→        match self {
    67→            Self::Duplicate | Self::Slashable => true,
    68→            Self::UniqueNonSlashable => false,
    69→        }
    70→    }
    71→    pub fn is_slashable(&self) -> bool {
    72→        matches!(self, Self::Slashable)
    73→    }
    74→}
    75→
    76→impl<E: EthSpec> ObservedBlockProducers<E> {
    77→    /// Observe that the `block` was produced by `block.proposer_index` at `block.slot`. This will
    78→    /// update `self` so future calls to it indicate that this block is known.
    79→    ///
    80→    /// The supplied `block` **MUST** be signature verified (see struct-level documentation).
    81→    ///
    82→    /// ## Errors
    83→    ///
    84→    /// - `block.proposer_index` is greater than `VALIDATOR_REGISTRY_LIMIT`.
    85→    /// - `block.slot` is equal to or less than the latest pruned `finalized_slot`.
    86→    pub fn observe_proposal(
    87→        &mut self,
    88→        block_root: Hash256,
    89→        block: BeaconBlockRef<'_, E>,
    90→    ) -> Result<SeenBlock, Error> {
    91→        self.sanitize_block(block)?;
    92→
    93→        let key = ProposalKey {
    94→            slot: block.slot(),
    95→            proposer: block.proposer_index(),
    96→        };
    97→
    98→        let entry = self.items.entry(key);
    99→
   100→        let slashable_proposal = match entry {
   101→            Entry::Occupied(mut occupied_entry) => {
   102→                let block_roots = occupied_entry.get_mut();
   103→                let newly_inserted = block_roots.insert(block_root);
   104→
   105→                let is_equivocation = block_roots.len() > 1;
   106→
   107→                if is_equivocation {
   108→                    SeenBlock::Slashable
   109→                } else if !newly_inserted {
   110→                    SeenBlock::Duplicate
   111→                } else {
   112→                    SeenBlock::UniqueNonSlashable
   113→                }
   114→            }
   115→            Entry::Vacant(vacant_entry) => {
   116→                let block_roots = HashSet::from([block_root]);
   117→                vacant_entry.insert(block_roots);
   118→
   119→                SeenBlock::UniqueNonSlashable
   120→            }
   121→        };
   122→
   123→        Ok(slashable_proposal)
   124→    }
   125→
   126→    /// Returns `Ok(true)` if the `block` has been observed before, `Ok(false)` if not. Does not
   127→    /// update the cache, so calling this function multiple times will continue to return
   128→    /// `Ok(false)`, until `Self::observe_proposer` is called.
   129→    ///
   130→    /// ## Errors
   131→    ///
   132→    /// - `block.proposer_index` is greater than `VALIDATOR_REGISTRY_LIMIT`.
   133→    /// - `block.slot` is equal to or less than the latest pruned `finalized_slot`.
   134→    pub fn proposer_has_been_observed(
   135→        &self,
   136→        block: BeaconBlockRef<'_, E>,
   137→        block_root: Hash256,
   138→    ) -> Result<SeenBlock, Error> {
   139→        self.sanitize_block(block)?;
   140→
   141→        let key = ProposalKey {
   142→            slot: block.slot(),
   143→            proposer: block.proposer_index(),
   144→        };
   145→
   146→        if let Some(block_roots) = self.items.get(&key) {
   147→            let block_already_known = block_roots.contains(&block_root);
   148→            let no_prev_known_blocks =
   149→                block_roots.difference(&HashSet::from([block_root])).count() == 0;
   150→
   151→            if !no_prev_known_blocks {
   152→                Ok(SeenBlock::Slashable)
   153→            } else if block_already_known {
   154→                Ok(SeenBlock::Duplicate)
   155→            } else {
   156→                Ok(SeenBlock::UniqueNonSlashable)
   157→            }
   158→        } else {
   159→            Ok(SeenBlock::UniqueNonSlashable)
   160→        }
   161→    }
   162→
   163→    /// Returns `Ok(())` if the given `block` is sane.
   164→    fn sanitize_block(&self, block: BeaconBlockRef<'_, E>) -> Result<(), Error> {
   165→        if block.proposer_index() >= E::ValidatorRegistryLimit::to_u64() {
   166→            return Err(Error::ValidatorIndexTooHigh(block.proposer_index()));
   167→        }
   168→
   169→        let finalized_slot = self.finalized_slot;
   170→        if finalized_slot > 0 && block.slot() <= finalized_slot {
   171→            return Err(Error::FinalizedBlock {
   172→                slot: block.slot(),
   173→                finalized_slot,
   174→            });
   175→        }
   176→
   177→        Ok(())
   178→    }
   179→
   180→    /// Removes all observations of blocks equal to or earlier than `finalized_slot`.
   181→    ///
   182→    /// Stores `finalized_slot` in `self`, so that `self` will reject any block that has a slot
   183→    /// equal to or less than `finalized_slot`.
   184→    ///
   185→    /// No-op if `finalized_slot == 0`.
   186→    pub fn prune(&mut self, finalized_slot: Slot) {
   187→        if finalized_slot == 0 {
   188→            return;
   189→        }
   190→
   191→        self.finalized_slot = finalized_slot;
   192→        self.items.retain(|key, _| key.slot > finalized_slot);
   193→    }
   194→
   195→    /// Returns `true` if the given `validator_index` has been stored in `self` at `epoch`.
   196→    ///
   197→    /// This is useful for doppelganger detection.
   198→    pub fn index_seen_at_epoch(&self, validator_index: u64, epoch: Epoch) -> bool {
   199→        self.items.iter().any(|(key, _)| {
   200→            key.slot.epoch(E::slots_per_epoch()) == epoch && key.proposer == validator_index
   201→        })
   202→    }
   203→}
